self.addEventListener('install', e => {
  e.waitUntil(caches.open(VERSION).then(c => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});

// Map tiles and photos of your own places are kept across app updates once viewed, so they still work offline
// (Wikimedia is blocked in China, so photos must be seen once before you fly).
const TILES = 'everywhen-tiles', TILE_MAX = 2500;
let tilePuts = 0;
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k !== VERSION && k !== TILES).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
async function trimTiles(cache) {
  const keys = await cache.keys();
  for (let i = 0; i < keys.length - TILE_MAX; i++) await cache.delete(keys[i]);
}

// Same-origin files: serve from cache straight away, refresh the cache in the background.
// Other hosts (weather, exchange rates) go straight to the network; the app handles failures itself.
self.addEventListener('fetch', e => {
  const req = e.request, url = new URL(req.url);
  if (req.method === 'GET' && (url.hostname === 'tile.openstreetmap.org' || /(^|\.)(upload|thumb)\.wikimedia\.org$/.test(url.hostname))) {
    e.respondWith(caches.open(TILES).then(async cache => {
      const hit = await cache.match(req); if (hit) return hit;
      try { const res = await fetch(req); if (res.ok) { cache.put(req, res.clone()); if (++tilePuts % 100 === 0) trimTiles(cache); } return res; }
      catch { return new Response('', { status: 504 }); }
    }));
    return;
  }
  if (req.method !== 'GET' || url.origin !== location.origin) return;
  e.respondWith(caches.open(VERSION).then(async cache => {
    const hit = await cache.match(req, { ignoreSearch: true }) || (req.mode === 'navigate' ? await cache.match('./index.html') : undefined);
    const net = fetch(req).then(res => { if (res.ok) cache.put(req, res.clone()); return res; }).catch(() => undefined);
    return hit || (await net) || new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } });
  }));
});
